recipes.code:
{
  "inputs": [
    {
      "id": "kms-api-key",
      "type": "promptString",
      "description": "Your KeepMySubs API key. Create one at https://keepmysubs.com/dashboard/settings (Settings → API keys), or run `kms auth login`.",
      "password": true
    }
  ],
  "servers": {
    "keepmysubs": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@keepmysubs/mcp@0.1.0"
      ],
      "env": {
        "KMS_API_KEY": "${input:kms-api-key}",
        "KMS_BASE_URL": "<kms-base-url>"
      }
    }
  }
}
